    36→    const [mutedPlatforms = getEmptyObject<Partial<Record<Platform, true>>>()] = useOnyx(ONYXKEYS.NVP_MUTED_PLATFORMS, {canBeMissing: true});
    37→    const isPlatformMuted = mutedPlatforms[platform];
    38→    const [account] = useOnyx(ONYXKEYS.ACCOUNT, {canBeMissing: false});
    39→    const [preferredTheme] = useOnyx(ONYXKEYS.PREFERRED_THEME, {canBeMissing: true});
    40→    const [preferredLocale] = useOnyx(ONYXKEYS.NVP_PREFERRED_LOCALE, {canBeMissing: true});
