    55→        >
    56→            <HeaderWithBackButton
    57→                title={translate('common.preferences')}
    58→                icon={illustrations.Gears}
    59→                shouldUseHeadlineHeader
    60→                shouldShowBackButton={shouldUseNarrowLayout}
    61→                shouldDisplaySearchRouter
    62→                onBackButtonPress={Navigation.popToSidebar}
    63→            />
    64→            <ScrollView contentContainerStyle={styles.pt3}>
    65→                <View style={[styles.flex1, shouldUseNarrowLayout ? styles.workspaceSectionMobile : styles.workspaceSection]}>
    66→                    <Section
    67→                        title={translate('preferencesPage.appSection.title')}
    68→                        titleStyles={styles.accountSettingsSectionTitle}
    69→                        isCentralPane
    70→                        illustrationContainerStyle={styles.cardSectionIllustrationContainer}
    71→                        illustrationBackgroundColor={colors.blue500}
    72→                        // eslint-disable-next-line react/jsx-props-no-spreading
    73→                        {...preferencesIllustration}
    74→                    >
    75→                        <View style={[styles.flex1, styles.mt5]}>
    76→                            <View style={[styles.flexRow, styles.mb4, styles.justifyContentBetween, styles.sectionMenuItemTopDescription]}>
    77→                                <View style={styles.flex4}>
    78→                                    <Text>{translate('preferencesPage.receiveRelevantFeatureUpdatesAndExpensifyNews')}</Text>
    79→                                </View>
    80→                                <View style={[styles.flex1, styles.alignItemsEnd]}>
    81→                                    <Switch
    82→                                        accessibilityLabel={translate('preferencesPage.receiveRelevantFeatureUpdatesAndExpensifyNews')}
    83→                                        isOn={account?.isSubscribedToNewsletter ?? true}
