    85→                                    />
    86→                                </View>
    87→                            </View>
    88→                            <View style={[styles.flexRow, styles.mb4, styles.justifyContentBetween]}>
    89→                                <View style={styles.flex4}>
    90→                                    <Text>{translate('preferencesPage.muteAllSounds')}</Text>
    91→                                </View>
    92→                                <View style={[styles.flex1, styles.alignItemsEnd]}>
    93→                                    <Switch
    94→                                        accessibilityLabel={translate('preferencesPage.muteAllSounds')}
    95→                                        isOn={isPlatformMuted ?? false}
    96→                                        onToggle={() => togglePlatformMute(platform, mutedPlatforms)}
    97→                                    />
    98→                                </View>
    99→                            </View>
   100→                            <MenuItemWithTopDescription
   101→                                shouldShowRightIcon
   102→                                title={translate(`priorityModePage.priorityModes.${priorityMode ?? CONST.PRIORITY_MODE.DEFAULT}.label`)}
   103→                                description={translate('priorityModePage.priorityMode')}
   104→                                onPress={() => Navigation.navigate(ROUTES.SETTINGS_PRIORITY_MODE)}
   105→                                wrapperStyle={styles.sectionMenuItemTopDescription}
   106→                            />
   107→                            <MenuItemWithTopDescription
   108→                                shouldShowRightIcon
   109→                                title={preferredLocale ? LOCALE_TO_LANGUAGE_STRING[preferredLocale] : undefined}
   110→                                description={translate('languagePage.language')}
   111→                                onPress={() => Navigation.navigate(ROUTES.SETTINGS_LANGUAGE)}
   112→                                wrapperStyle={styles.sectionMenuItemTopDescription}
   113→                                hintText={!preferredLocale || !isFullySupportedLocale(preferredLocale) ? translate('languagePage.aiGenerated') : ''}
   114→                            />
   115→                            <MenuItemWithTopDescription
   116→                                shouldShowRightIcon
   117→                                title={`${paymentCurrency} - ${getCurrencySymbol(paymentCurrency)}`}
   118→                                description={translate('billingCurrency.paymentCurrency')}
